package bolonhaemilano;

/** Testes manuais automatizados: prepara, executa e verifica sem bibliotecas externas. */
public final class Testes {
    private static int aprovados=0, reprovados=0;
    private Testes() { }
    public static void main(String[] args){
        testarCidade(); testarMercado(); testarAgricultura(); testarGoverno(); testarConstrucoes(); testarNobreza(); testarPartida();
        System.out.println("\nResultado: "+aprovados+" aprovados; "+reprovados+" reprovados.");
        if(reprovados>0)System.exit(1);
    }
    private static void verificar(String nome,boolean ok){if(ok){aprovados++;System.out.println("[OK] "+nome);}else{reprovados++;System.out.println("[FALHA] "+nome);}}
    private static Cidade cidade(){return new Cidade("Bolonha",new Jogador("Teste"));}
    private static void testarCidade(){Cidade c=cidade();verificar("valores iniciais",c.getFlorins()==1000&&c.getAnoAtual()==1400&&c.getTerras()==10000&&c.getGraos()==500&&c.getServos()==200);verificar("recusa remoção acima do saldo",!c.removerFlorins(1001)&&c.getFlorins()==1000);verificar("recusa quantidade zero",!c.removerGraos(0));c.marcarColheitaFeita();c.marcarImpostosArrecadados();c.avancarAno();verificar("ano avança",c.getAnoAtual()==1401);verificar("virada libera ações anuais",!c.isColheitaFeita()&&!c.isImpostosArrecadados());}
    private static void testarMercado(){Mercado m=new Mercado();Cidade c=cidade();verificar("compra 100 grãos",m.comprarGraos(c,100));verificar("compra debita 200 florins",c.getFlorins()==800);verificar("compra acrescenta grãos",c.getGraos()==600);verificar("recusa compra negativa",!m.comprarGraos(c,-2));verificar("recusa compra sem saldo",!m.comprarTerras(c,2000));verificar("venda de grãos",m.venderGraos(c,50)&&c.getFlorins()==900);verificar("venda não permite estoque negativo",!m.venderTerras(c,20000));verificar("preços seguem tabela",m.getPrecoGrao()==2&&m.getPrecoTerra()==1);}
    private static void testarAgricultura(){Agricultura a=new Agricultura();Cidade c=cidade();verificar("colheita inicial de 1000 hectares",a.processarColheita(c)==1000);verificar("estoque após colheita é 2000 grãos",c.getGraos()==2000);verificar("não colhe duas vezes no mesmo ano",a.processarColheita(c)==-1);verificar("percentual abaixo do mínimo é recusado",!a.distribuirAlimentos(c,10));verificar("percentual acima do máximo é recusado",!a.distribuirAlimentos(c,90));verificar("distribuição válida é aceita",a.distribuirAlimentos(c,20));}
    private static void testarGoverno(){Governo g=new Governo();Cidade c=cidade();verificar("taxa acima de 50 é recusada",!g.definirTaxaImposto(c,60));verificar("taxa válida é aceita",g.definirTaxaImposto(c,10));verificar("justiça desconhecida é recusada",!g.definirJustica(c,"Branda"));verificar("justiça severa é aceita",g.definirJustica(c,"Severa"));verificar("arrecada 26 florins com justiça severa",g.arrecadarImpostos(c)==26);verificar("não arrecada duas vezes no ano",g.arrecadarImpostos(c)==-1);}
    private static void testarConstrucoes(){Construcoes b=new Construcoes();Cidade c=cidade();c.removerServos(150);verificar("recrutamento sem servos é recusado",!b.recrutarSoldados(c,100));verificar("falha não debita florins",c.getFlorins()==1000);Cidade d=cidade();verificar("recruta soldados com recursos",b.recrutarSoldados(d,10));verificar("recrutamento debita florins e servos",d.getFlorins()==950&&d.getServos()==190&&d.getSoldados()==10);Cidade e=cidade();verificar("construir dez unidades",b.construir(e,10));verificar("construção custa 200 florins",e.getFlorins()==800&&e.getConstrucoes()==10);verificar("quantidade negativa é recusada",!b.construir(e,-1));}
    private static void testarNobreza(){Nobreza n=new Nobreza();Cidade c=cidade();verificar("prestígio inicial é 300",n.calcularPrestigio(c)==300);verificar("300 não promove",!n.verificarPromocao(c));c.adicionarConstrucoes(10);verificar("400 promove a Barão",n.verificarPromocao(c)&&c.getDono().getTitulo().equals("Barão"));verificar("uma chamada promove apenas um título",c.getDono().getNivelTitulo()==1);Jogador rei=new Jogador("Topo");for(int i=0;i<5;i++)rei.promover();verificar("monarca não ultrapassa último título",rei.ehMonarca()&&!rei.promover());}
    private static void testarPartida(){Partida p=new Partida();Cidade a=new Cidade("Bolonha",new Jogador("A")),b=new Cidade("Milano",new Jogador("B"));verificar("adiciona primeira cidade",p.adicionarCidade(a));verificar("adiciona segunda cidade",p.adicionarCidade(b));verificar("primeiro jogador inicia",p.getCidadeAtual()==a);verificar("primeiro turno não fecha ano",!p.passarTurno()&&p.getCidadeAtual()==b);verificar("último turno fecha ano",p.passarTurno());p.encerrarAno(new Nobreza());verificar("ano avança para ambas cidades",a.getAnoAtual()==1401&&b.getAnoAtual()==1401);verificar("partida não termina no início",!p.terminou());Partida limite=new Partida();for(int i=0;i<4;i++)verificar("adiciona jogador permitido "+(i+1),limite.adicionarCidade(new Cidade("C"+i,new Jogador("J"+i))));verificar("recusa quinta cidade",!limite.adicionarCidade(new Cidade("Extra",new Jogador("Extra"))));}
}
